// Some portions generated by Co-Pilot
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.lmdb.LmdbBackupDeltaCodec.NamespaceOperation;
import org.eclipse.rdf4j.sail.lmdb.LmdbBackupDeltaCodec.Record;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbBackupRecordBufferTest {
	@Test
	void smallSnapshotsRemainImmutableAfterReset(@TempDir Path directory) throws Exception {
		try (var buffer = new LmdbBackupRecordBuffer(directory)) {
			Record record = new Record(NamespaceOperation.SET, "p", "urn:p:");
			buffer.add(record);
			List<Record> snapshot = buffer.snapshot(List.of());
			buffer.clear();
			buffer.add(new Record(NamespaceOperation.CLEAR, null, null));
			assertEquals(List.of(record), snapshot);
			assertThrows(UnsupportedOperationException.class, () -> snapshot.clear());
			assertEquals(0, fileCount(directory));
		}
	}

	@Test
	void spilledRecordsProduceIdenticalJournalBytesInOrder(@TempDir Path directory) throws Exception {
		try (var buffer = new LmdbBackupRecordBuffer(directory, 128)) {
			var vf = SimpleValueFactory.getInstance();
			List<Record> expected = new ArrayList<>();
			for (int i = 0; i < 1000; i++) {
				Record record = new Record(i % 2 == 0, i % 3 == 0,
						vf.createStatement(vf.createIRI("urn:s:" + i), vf.createIRI("urn:p"),
								vf.createLiteral("value " + i), vf.createBNode("context")));
				expected.add(record);
				buffer.add(record);
			}
			List<Record> suffix = List.of(new Record(NamespaceOperation.REMOVE, "old", null),
					new Record(NamespaceOperation.SET, "new", "urn:new:"));
			List<Record> snapshot = buffer.snapshot(suffix);
			expected.addAll(suffix);
			assertEquals(1, fileCount(directory));
			assertEquals(expected.size(), snapshot.size());
			assertArrayEquals(journal(expected), journal(snapshot));
			assertArrayEquals(journal(expected), journal(snapshot));
			assertEquals("value 500", snapshot.get(500).getStatement().getObject().stringValue());
			assertThrows(UnsupportedOperationException.class, () -> snapshot.clear());
			buffer.clear();
			assertEquals(0, fileCount(directory));
			assertThrows(IllegalStateException.class, () -> snapshot.iterator());
		}
	}

	@Test
	void oneLargeRecordSpillsAndAbandonedReadersCloseOnReset(@TempDir Path directory) throws Exception {
		try (var buffer = new LmdbBackupRecordBuffer(directory, 128)) {
			buffer.add(new Record(NamespaceOperation.SET, "p", "x".repeat(4096)));
			buffer.add(new Record(NamespaceOperation.CLEAR, null, null));
			var iterator = buffer.snapshot(List.of()).iterator();
			assertEquals(4096, iterator.next().getNamespaceName().length());
			assertEquals(1, fileCount(directory));
			buffer.clear();
			assertEquals(0, fileCount(directory));
			assertThrows(IllegalStateException.class, () -> iterator.next());
			buffer.add(new Record(NamespaceOperation.SET, "reused", "urn:reused:"));
			assertEquals("reused", buffer.snapshot(List.of()).getFirst().getNamespacePrefix());
		}
		assertEquals(0, fileCount(directory));
	}

	@Test
	void spillFailureCannotPublishAnIncompleteDelta(@TempDir Path directory) throws Exception {
		Path missing = directory.resolve("missing");
		try (var buffer = new LmdbBackupRecordBuffer(missing, 0)) {
			Record record = new Record(NamespaceOperation.CLEAR, null, null);
			assertThrows(UncheckedIOException.class, () -> buffer.add(record));
			assertThrows(UncheckedIOException.class, () -> buffer.snapshot(List.of()));
			assertThrows(UncheckedIOException.class, () -> buffer.add(record));
			buffer.clear();
			Files.createDirectory(missing);
			buffer.add(record);
			assertEquals(NamespaceOperation.CLEAR, buffer.snapshot(List.of()).getFirst().getNamespaceOperation());
		}
		assertEquals(0, fileCount(missing));
	}

	@Test
	void streamingValidationChecksTheCompleteJournalBody() throws Exception {
		byte[] bytes = journal(List.of(new Record(NamespaceOperation.SET, "p", "urn:p:"),
				new Record(NamespaceOperation.REMOVE, "p", null)));
		assertEquals(37, LmdbBackupDeltaCodec.validateJournal(new ByteArrayInputStream(bytes)));
		for (int length = 0; length < bytes.length; length++) {
			byte[] truncated = Arrays.copyOf(bytes, length);
			assertThrows(IOException.class,
					() -> LmdbBackupDeltaCodec.validateJournal(new ByteArrayInputStream(truncated)));
		}
		byte[] corrupted = bytes.clone();
		corrupted[corrupted.length - 6] = 127;
		assertThrows(IOException.class,
				() -> LmdbBackupDeltaCodec.validateJournal(new ByteArrayInputStream(corrupted)));
	}

	private static byte[] journal(List<Record> records) throws Exception {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		LmdbBackupDeltaCodec.write(bytes, records, 37);
		return bytes.toByteArray();
	}

	private static long fileCount(Path directory) throws Exception {
		try (var files = Files.list(directory)) {
			return files.count();
		}
	}
}
